-- Schema definition for Lesson Plan AutoFill System

-- Enable UUID extension if needed
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Drop tables if they exist
DROP TABLE IF EXISTS "System_Logs" CASCADE;
DROP TABLE IF EXISTS "LessonPlan_Backup" CASCADE;
DROP TABLE IF EXISTS "LessonPlans" CASCADE;
DROP TABLE IF EXISTS "BasicOptions" CASCADE;
DROP TABLE IF EXISTS "Indicators" CASCADE;
DROP TABLE IF EXISTS "LessonTopics" CASCADE;
DROP TABLE IF EXISTS "Units" CASCADE;
DROP TABLE IF EXISTS "Subjects" CASCADE;
DROP TABLE IF EXISTS "AppConfig" CASCADE;

-- 1. AppConfig Table
CREATE TABLE "AppConfig" (
    "configKey" VARCHAR(255) PRIMARY KEY,
    "configValue" TEXT,
    "description" TEXT,
    "isActive" BOOLEAN DEFAULT TRUE,
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Subjects Table
CREATE TABLE "Subjects" (
    "subjectId" VARCHAR(255) PRIMARY KEY,
    "subjectCode" VARCHAR(255) NOT NULL,
    "subjectName" VARCHAR(255) NOT NULL,
    "learningArea" VARCHAR(255) NOT NULL,
    "gradeLevel" VARCHAR(255) NOT NULL,
    "semester" VARCHAR(50),
    "courseType" VARCHAR(100),
    "allowManualCode" BOOLEAN DEFAULT FALSE,
    "isActive" BOOLEAN DEFAULT TRUE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Units Table
CREATE TABLE "Units" (
    "unitId" VARCHAR(255) PRIMARY KEY,
    "subjectId" VARCHAR(255) REFERENCES "Subjects"("subjectId") ON DELETE CASCADE,
    "unitNumber" INTEGER NOT NULL,
    "unitName" VARCHAR(255) NOT NULL,
    "indicatorIds" TEXT,
    "isActive" BOOLEAN DEFAULT TRUE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. LessonTopics Table
CREATE TABLE "LessonTopics" (
    "topicId" VARCHAR(255) PRIMARY KEY,
    "unitId" VARCHAR(255) REFERENCES "Units"("unitId") ON DELETE CASCADE,
    "topicNumber" INTEGER NOT NULL,
    "lessonTopic" VARCHAR(255) NOT NULL,
    "defaultHours" INTEGER DEFAULT 1,
    "isActive" BOOLEAN DEFAULT TRUE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. Indicators Table
CREATE TABLE "Indicators" (
    "indicatorId" VARCHAR(255) PRIMARY KEY,
    "learningArea" VARCHAR(255) NOT NULL,
    "gradeLevel" VARCHAR(255) NOT NULL,
    "standardCode" VARCHAR(255) NOT NULL,
    "standardText" TEXT NOT NULL,
    "indicatorType" VARCHAR(50) NOT NULL,
    "indicatorCode" VARCHAR(255) NOT NULL,
    "indicatorText" TEXT NOT NULL,
    "isActive" BOOLEAN DEFAULT TRUE,
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 6. BasicOptions Table
CREATE TABLE "BasicOptions" (
    "optionId" VARCHAR(255) PRIMARY KEY,
    "optionType" VARCHAR(255) NOT NULL,
    "optionName" VARCHAR(255) NOT NULL,
    "optionText" TEXT,
    "gradeLevel" VARCHAR(255),
    "subjectId" VARCHAR(255),
    "isActive" BOOLEAN DEFAULT TRUE
);

-- 7. LessonPlans Table
CREATE TABLE "LessonPlans" (
    "planId" VARCHAR(255) PRIMARY KEY,
    "planStatus" VARCHAR(50) NOT NULL DEFAULT 'draft',
    "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "updatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "pdfUrl" TEXT,
    "pdfCreatedAt" TIMESTAMP WITH TIME ZONE,
    "wordUrl" TEXT,
    "wordCreatedAt" TIMESTAMP WITH TIME ZONE,
    
    -- Document Header
    "teacherName" VARCHAR(255),
    "schoolName" VARCHAR(255),
    "organization" VARCHAR(255),
    "headerLearningArea" VARCHAR(255),
    "headerGradeLevel" VARCHAR(255),
    
    -- Subject & Term
    "subjectId" VARCHAR(255),
    "subjectName" VARCHAR(255),
    "subjectCode" VARCHAR(255),
    "learningArea" VARCHAR(255),
    "gradeLevel" VARCHAR(255),
    "semester" VARCHAR(50),
    "academicYear" VARCHAR(50),
    "totalHours" INTEGER,
    
    -- Unit & Topic
    "unitId" VARCHAR(255),
    "unitName" VARCHAR(255),
    "topicId" VARCHAR(255),
    "lessonTopic" VARCHAR(255),
    
    -- Standards & Content
    "learningStandard" TEXT,
    "indicatorDuring" TEXT,
    "indicatorFinal" TEXT,
    "indicatorSelectedIds" TEXT,
    "essentialConcept" TEXT,
    "objectiveK" TEXT,
    "objectiveP" TEXT,
    "objectiveA" TEXT,
    "learningContent" TEXT,
    "competencies" TEXT,
    "desiredAttributes" TEXT,
    "skills21" TEXT,
    "learningProcess" TEXT,
    
    -- Assessment Table (K/P/A)
    "measureK" TEXT, "methodK" TEXT, "toolK" TEXT, "criteriaK" TEXT, "rubricK" TEXT,
    "measureP" TEXT, "methodP" TEXT, "toolP" TEXT, "criteriaP" TEXT, "rubricP" TEXT,
    "measureA" TEXT, "methodA" TEXT, "toolA" TEXT, "criteriaA" TEXT, "rubricA" TEXT,
    
    -- Resources & Tasks
    "learningMedia" TEXT,
    "learningSources" TEXT,
    "tasks" TEXT,
    
    -- Review
    "resultK" TEXT,
    "resultP" TEXT,
    "resultA" TEXT,
    "problems" TEXT,
    "solutions" TEXT
);

-- 8. LessonPlan_Backup Table
CREATE TABLE "LessonPlan_Backup" (
    "backupId" VARCHAR(255) PRIMARY KEY,
    "originalPlanId" VARCHAR(255) REFERENCES "LessonPlans"("planId") ON DELETE CASCADE,
    "backupAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "actionType" VARCHAR(100) NOT NULL,
    "backupReason" TEXT,
    "backupDataJson" TEXT NOT NULL
);

-- 9. System_Logs Table
CREATE TABLE "System_Logs" (
    "logId" VARCHAR(255) PRIMARY KEY,
    "timestamp" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "action" VARCHAR(255) NOT NULL,
    "status" VARCHAR(50) NOT NULL,
    "planId" VARCHAR(255),
    "message" TEXT,
    "errorCode" VARCHAR(100),
    "userEmail" VARCHAR(255)
);

-- Indexing for fast loading
CREATE INDEX idx_units_subject ON "Units" ("subjectId");
CREATE INDEX idx_topics_unit ON "LessonTopics" ("unitId");
CREATE INDEX idx_plans_status ON "LessonPlans" ("planStatus");
CREATE INDEX idx_backup_plan ON "LessonPlan_Backup" ("originalPlanId");


