INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-09', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ป.4', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ป.4/5', 'พูดแสดงความรู้สึกของตนเองเกี่ยวกับเรื่องต่าง ๆ ใกล้ตัว และกิจกรรมต่าง ๆ ตามแบบที่ฟัง', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-10', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ป.4', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ป.4/1', 'พูด/เขียนให้ข้อมูลเกี่ยวกับตนเองและเรื่องใกล้ตัว', TRUE);
