INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-13', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.4', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'final', 'ต 2.1 ป.4/1', 'พูดและทำท่าประกอบอย่างสุภาพตามมารยาทสังคมและวัฒนธรรมของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-14', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.4', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'final', 'ต 2.1 ป.4/2', 'ตอบคำถามเกี่ยวกับเทศกาล/วันสำคัญ/งานฉลอง และชีวิตความเป็นอยู่ง่าย ๆ ของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-15', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.4', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ป.4/3', 'เข้าร่วมกิจกรรมทางภาษาและวัฒนธรรมที่เหมาะกับวัย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-04-16', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.4', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ป.4/1', 'บอกความแตกต่างของเสียงตัวอักษร คำ กลุ่มคำ ประโยค และข้อความของภาษาต่างประเทศและภาษาไทย', TRUE);
