INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-13', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.5', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'final', 'ต 2.1 ป.5/1', 'ใช้ถ้อยคำ น้ำเสียง และกิริยาท่าทางอย่างสุภาพตามมารยาทสังคมและวัฒนธรรมของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-14', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.5', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'final', 'ต 2.1 ป.5/2', 'ตอบคำถาม/บอกความสำคัญของเทศกาล/วันสำคัญ/งานฉลอง และชีวิตความเป็นอยู่ง่าย ๆ ของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-15', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.5', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ป.5/3', 'เข้าร่วมกิจกรรมทางภาษาและวัฒนธรรมตามความสนใจ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-16', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.5', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ป.5/1', 'บอกความเหมือน/ความแตกต่างระหว่างการออกเสียงประโยคชนิดต่าง ๆ การใช้เครื่องหมายวรรคตอน และการลำดับคำตามโครงสร้างประโยคของภาษาต่างประเทศและภาษาไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-17', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.5', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ป.5/2', 'บอกความเหมือน/ความแตกต่างระหว่างเทศกาลและงานฉลองของเจ้าของภาษากับของไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ป.5', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'final', 'ต 3.1 ป.5/1', 'ค้นคว้า รวบรวมคำศัพท์ที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่น และนำเสนอด้วยการพูด/การเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ป.5', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ป.5/1', 'ฟัง พูด และอ่าน/เขียนในสถานการณ์ต่าง ๆ ที่เกิดขึ้นในห้องเรียนและสถานศึกษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-05-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ป.5', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ป.5/1', 'ใช้ภาษาต่างประเทศในการสืบค้นและรวบรวมข้อมูลต่าง ๆ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-06-01', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ป.6', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ป.6/1', 'ปฏิบัติตามคำสั่ง คำขอร้อง และคำแนะนำที่ฟังและอ่าน', TRUE);
