INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-06-17', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ป.6', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ป.6/2', 'เปรียบเทียบความเหมือน/ความแตกต่างระหว่างเทศกาล งานฉลอง และประเพณีของเจ้าของภาษากับของไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-06-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ป.6', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'final', 'ต 3.1 ป.6/1', 'ค้นคว้า รวบรวมคำศัพท์ที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งการเรียนรู้ และนำเสนอด้วยการพูด/การเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-06-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ป.6', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ป.6/1', 'ใช้ภาษาสื่อสารในสถานการณ์ต่าง ๆ ที่เกิดขึ้นในห้องเรียนและสถานศึกษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-06-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ป.6', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ป.6/1', 'ใช้ภาษาต่างประเทศในการสืบค้นและรวบรวมข้อมูลต่าง ๆ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-01', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.1/1', 'ปฏิบัติตามคำสั่ง คำขอร้อง คำแนะนำ และคำชี้แจงง่าย ๆ ที่ฟังและอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-02', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.1/2', 'อ่านออกเสียงข้อความ นิทาน และบทร้อยกรองสั้น ๆ ถูกต้องตามหลักการอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-03', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.1/3', 'เลือก/ระบุประโยคและข้อความให้สัมพันธ์กับสื่อที่ไม่ใช่ความเรียงที่อ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-04', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.1/4', 'ระบุหัวข้อเรื่อง ใจความสำคัญ และตอบคำถามจากการฟังและอ่านบทสนทนา นิทาน และเรื่องสั้น', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-05', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.1/1', 'สนทนาแลกเปลี่ยนข้อมูลเกี่ยวกับตนเอง กิจกรรม และสถานการณ์ต่าง ๆ ในชีวิตประจำวัน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-06', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.1/2', 'ใช้คำขอร้อง ให้คำแนะนำ และคำชี้แจงตามสถานการณ์', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-07', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.1/3', 'พูดและเขียนแสดงความต้องการ ขอความช่วยเหลือ ตอบรับ และปฏิเสธการให้ความช่วยเหลือในสถานการณ์ต่าง ๆ อย่างเหมาะสม', TRUE);
