INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-09', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.1', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.1/5', 'พูดและเขียนแสดงความรู้สึกและความคิดเห็นของตนเองเกี่ยวกับเรื่องต่าง ๆ ใกล้ตัว กิจกรรมต่าง ๆ พร้อมทั้งให้เหตุผลสั้น ๆ ประกอบอย่างเหมาะสม', TRUE);
