INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-17', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.1', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ม.1/2', 'เปรียบเทียบความเหมือนและความแตกต่างระหว่างเทศกาล งานฉลอง วันสำคัญ และชีวิตความเป็นอยู่ของเจ้าของภาษากับของไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ม.1', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'during', 'ต 3.1 ม.1/1', 'ค้นคว้า รวบรวม และสรุปข้อมูล/ข้อเท็จจริงที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งการเรียนรู้ และนำเสนอด้วยการพูด/การเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.1', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ม.1/1', 'ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียนและสถานศึกษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-07-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.1', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.1/1', 'ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้าความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-01', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.2/1', 'ปฏิบัติตามคำขอร้อง คำแนะนำ คำชี้แจง และคำอธิบายง่าย ๆ ที่ฟังและอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-02', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.2/2', 'อ่านออกเสียงข้อความ ข่าว ประกาศ และบทร้อยกรองสั้น ๆ ถูกต้องตามหลักการอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-03', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.2/3', 'ระบุ/เขียนประโยคและข้อความให้สัมพันธ์กับสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ที่อ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-04', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.2/4', 'เลือกหัวข้อเรื่อง ใจความสำคัญ บอกรายละเอียดสนับสนุน และแสดงความคิดเห็นเกี่ยวกับเรื่องที่ฟังและอ่าน พร้อมทั้งให้เหตุผลและยกตัวอย่างง่าย ๆ ประกอบ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-05', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.2/1', 'สนทนาแลกเปลี่ยนข้อมูลเกี่ยวกับตนเอง เรื่องต่าง ๆ ใกล้ตัว และสถานการณ์ต่าง ๆ ในชีวิตประจำวันอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-06', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.2/2', 'ใช้คำขอร้อง ให้คำแนะนำ คำชี้แจง และคำอธิบายตามสถานการณ์', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-07', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.2/3', 'พูดและเขียนแสดงความต้องการ เสนอและให้ความช่วยเหลือ ตอบรับ และปฏิเสธการให้ความช่วยเหลือในสถานการณ์ต่าง ๆ อย่างเหมาะสม', TRUE);
