INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-09', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.2/5', 'พูดและเขียนแสดงความรู้สึกและความคิดเห็นของตนเองเกี่ยวกับเรื่องต่าง ๆ กิจกรรม และประสบการณ์ พร้อมทั้งให้เหตุผลประกอบอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-10', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.2', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ม.2/1', 'พูดและเขียนบรรยายเกี่ยวกับตนเอง กิจวัตรประจำวัน ประสบการณ์ และข่าว/เหตุการณ์ที่อยู่ในความสนใจของสังคม', TRUE);
