INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ม.2', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'during', 'ต 3.1 ม.2/1', 'ค้นคว้า รวบรวม และสรุปข้อมูล/ข้อเท็จจริงที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งการเรียนรู้ และนำเสนอด้วยการพูด/การเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.2', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ม.2/1', 'ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียน สถานศึกษา และชุมชน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.2', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.2/1', 'ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้า รวบรวม และสรุปความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-08-21', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.2', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.2/2', 'เผยแพร่/ประชาสัมพันธ์ข้อมูลข่าวสารของโรงเรียนเป็นภาษาต่างประเทศ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-01', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.3/1', 'ปฏิบัติตามคำขอร้อง คำแนะนำ คำชี้แจง และคำอธิบายที่ฟังและอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-02', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.3/2', 'อ่านออกเสียงข้อความ ข่าว โฆษณา และบทร้อยกรองสั้น ๆ ถูกต้องตามหลักการอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-03', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.3/3', 'ระบุและเขียนสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ให้สัมพันธ์กับประโยคและข้อความที่ฟังหรืออ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-04', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.3/4', 'เลือก/ระบุหัวข้อเรื่อง ใจความสำคัญ รายละเอียดสนับสนุน และแสดงความคิดเห็นเกี่ยวกับเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ พร้อมทั้งให้เหตุผลและยกตัวอย่างประกอบ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-05', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.3/1', 'สนทนาและเขียนโต้ตอบข้อมูลเกี่ยวกับตนเอง เรื่องต่าง ๆ ใกล้ตัว สถานการณ์ ข่าว เรื่องที่อยู่ในความสนใจของสังคม และสื่อสารอย่างต่อเนื่องและเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-06', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.3/2', 'ใช้คำขอร้อง ให้คำแนะนำ คำชี้แจง และคำอธิบายอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-07', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.3/3', 'พูดและเขียนแสดงความต้องการ เสนอและให้ความช่วยเหลือ ตอบรับ และปฏิเสธการให้ความช่วยเหลือในสถานการณ์ต่าง ๆ อย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-08', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.3/4', 'พูดและเขียนเพื่อขอและให้ข้อมูล อธิบาย เปรียบเทียบ และแสดงความคิดเห็นเกี่ยวกับเรื่องที่ฟังหรืออ่านอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-09', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.3/5', 'พูดและเขียนบรรยายความรู้สึกและความคิดเห็นของตนเองเกี่ยวกับเรื่องต่าง ๆ กิจกรรม ประสบการณ์ และข่าว/เหตุการณ์ พร้อมทั้งให้เหตุผลประกอบอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-10', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ม.3/1', 'พูดและเขียนบรรยายเกี่ยวกับตนเอง ประสบการณ์ ข่าว/เหตุการณ์ เรื่อง/ประเด็นต่าง ๆ ที่อยู่ในความสนใจของสังคม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-11', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'final', 'ต 1.3 ม.3/2', 'พูดและเขียนสรุปใจความสำคัญ/แก่นสาระ หัวข้อเรื่องที่ได้จากการวิเคราะห์เรื่อง ข่าว เหตุการณ์ และสถานการณ์ที่อยู่ในความสนใจของสังคม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-12', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.3', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ม.3/3', 'พูดและเขียนแสดงความคิดเห็นเกี่ยวกับกิจกรรม ประสบการณ์ และเหตุการณ์ พร้อมทั้งให้เหตุผลประกอบ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-13', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.3', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.3/1', 'เลือกใช้ภาษา น้ำเสียง และกิริยาท่าทางเหมาะกับบุคคลและโอกาสตามมารยาทสังคมและวัฒนธรรมของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-14', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.3', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.3/2', 'อธิบายเกี่ยวกับชีวิตความเป็นอยู่ ขนบธรรมเนียม และประเพณีของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-15', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.3', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.3/3', 'เข้าร่วม/จัดกิจกรรมทางภาษาและวัฒนธรรมตามความสนใจ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-16', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.3', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ม.3/1', 'เปรียบเทียบและอธิบายความเหมือนและความแตกต่างระหว่างการออกเสียงประโยคชนิดต่าง ๆ และการลำดับคำตามโครงสร้างประโยคของภาษาต่างประเทศและภาษาไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-17', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.3', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ม.3/2', 'เปรียบเทียบและอธิบายความเหมือนและความแตกต่างระหว่างชีวิตความเป็นอยู่และวัฒนธรรมของเจ้าของภาษากับของไทย และนำไปใช้อย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ม.3', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'during', 'ต 3.1 ม.3/1', 'ค้นคว้า รวบรวม และสรุปข้อมูล/ข้อเท็จจริงที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งการเรียนรู้ และนำเสนอด้วยการพูดและการเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.3', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ม.3/1', 'ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียน สถานศึกษา ชุมชน และสังคม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.3', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.3/1', 'ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้า รวบรวม และสรุปความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-09-21', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.3', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.3/2', 'เผยแพร่/ประชาสัมพันธ์ข้อมูลข่าวสารของโรงเรียน ชุมชน และท้องถิ่นเป็นภาษาต่างประเทศ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-01', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.4-6/1', 'ปฏิบัติตามคำแนะนำในคู่มือการใช้งานต่าง ๆ คำชี้แจง คำอธิบาย และคำบรรยายที่ฟังและอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-02', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.4-6/2', 'อ่านออกเสียงข้อความ ข่าว ประกาศ โฆษณา บทร้อยกรอง และบทละครสั้นถูกต้องตามหลักการอ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-03', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'final', 'ต 1.1 ม.4-6/3', 'อธิบายและเขียนประโยคและข้อความให้สัมพันธ์กับสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ที่อ่าน รวมทั้งระบุและเขียนสื่อที่ไม่ใช่ความเรียงรูปแบบต่าง ๆ ให้สัมพันธ์กับประโยคและข้อความที่ฟังหรืออ่าน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-04', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.1', 'เข้าใจและตีความเรื่องที่ฟังและอ่านจากสื่อประเภทต่าง ๆ และแสดงความคิดเห็นอย่างมีเหตุผล', 'during', 'ต 1.1 ม.4-6/4', 'จับใจความสำคัญ วิเคราะห์ความ สรุปความ ตีความ และแสดงความคิดเห็นจากการฟังและอ่านเรื่องที่เป็นสารคดีและบันเทิงคดี พร้อมทั้งให้เหตุผลและยกตัวอย่างประกอบ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-05', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.4-6/1', 'สนทนาและเขียนโต้ตอบข้อมูลเกี่ยวกับตนเองและเรื่องต่าง ๆ ใกล้ตัว ประสบการณ์ สถานการณ์ ข่าว/เหตุการณ์ ประเด็นที่อยู่ในความสนใจของสังคม และสื่อสารอย่างต่อเนื่องและเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-06', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.4-6/2', 'เลือกและใช้คำขอร้อง ให้คำแนะนำ คำชี้แจง และคำอธิบายอย่างคล่องแคล่ว', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-07', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.4-6/3', 'พูดและเขียนแสดงความต้องการ เสนอ ตอบรับ และปฏิเสธการให้ความช่วยเหลือในสถานการณ์จำลองหรือสถานการณ์จริงอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-08', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'final', 'ต 1.2 ม.4-6/4', 'พูดและเขียนเพื่อขอและให้ข้อมูล บรรยาย อธิบาย เปรียบเทียบ และแสดงความคิดเห็นเกี่ยวกับเรื่อง/ประเด็น/ข่าว/เหตุการณ์ที่ฟังและอ่านอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-09', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.2', 'มีทักษะการสื่อสารทางภาษาในการแลกเปลี่ยนข้อมูลข่าวสาร แสดงความรู้สึก และความคิดเห็นอย่างมีประสิทธิภาพ', 'during', 'ต 1.2 ม.4-6/5', 'พูดและเขียนบรรยายความรู้สึกและแสดงความคิดเห็นของตนเองเกี่ยวกับเรื่องต่าง ๆ กิจกรรม ประสบการณ์ และข่าว/เหตุการณ์อย่างมีเหตุผล', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-10', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'final', 'ต 1.3 ม.4-6/1', 'พูดและเขียนนำเสนอข้อมูลเกี่ยวกับตนเอง ประสบการณ์ ข่าว/เหตุการณ์ เรื่องและประเด็นต่าง ๆ ที่อยู่ในความสนใจของสังคม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-11', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ม.4-6/2', 'พูดและเขียนสรุปใจความสำคัญ/แก่นสาระที่ได้จากการวิเคราะห์เรื่อง กิจกรรม ข่าว เหตุการณ์ และสถานการณ์ตามความสนใจ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-12', 'สาระที่ 1 ภาษาเพื่อการสื่อสาร', 'ม.4-6', 'ต 1.3', 'นำเสนอข้อมูลข่าวสาร ความคิดรวบยอด และความคิดเห็นในเรื่องต่าง ๆ โดยการพูดและการเขียน', 'during', 'ต 1.3 ม.4-6/3', 'พูดและเขียนแสดงความคิดเห็นเกี่ยวกับกิจกรรม ประสบการณ์ และเหตุการณ์ทั้งในท้องถิ่น สังคม และโลก พร้อมทั้งให้เหตุผลและยกตัวอย่างประกอบ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-13', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.4-6', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.4-6/1', 'เลือกใช้ภาษา น้ำเสียง และกิริยาท่าทางเหมาะกับระดับของบุคคล โอกาส และสถานที่ตามมารยาทสังคมและวัฒนธรรมของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-14', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.4-6', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.4-6/2', 'อธิบาย/อภิปรายวิถีชีวิต ความคิด ความเชื่อ และที่มาของขนบธรรมเนียมและประเพณีของเจ้าของภาษา', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-15', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.4-6', 'ต 2.1', 'เข้าใจความสัมพันธ์ระหว่างภาษากับวัฒนธรรมของเจ้าของภาษา และนำไปใช้ได้อย่างเหมาะสมกับกาลเทศะ', 'during', 'ต 2.1 ม.4-6/3', 'เข้าร่วม แนะนำ และจัดกิจกรรมทางภาษาและวัฒนธรรมอย่างเหมาะสม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-16', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.4-6', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ม.4-6/1', 'อธิบาย/เปรียบเทียบความแตกต่างระหว่างโครงสร้างประโยค ข้อความ สำนวน คำพังเพย สุภาษิต และบทกลอนของภาษาต่างประเทศและภาษาไทย', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-17', 'สาระที่ 2 ภาษาและวัฒนธรรม', 'ม.4-6', 'ต 2.2', 'เข้าใจความเหมือนและความแตกต่างระหว่างภาษาและวัฒนธรรมของเจ้าของภาษากับภาษาและวัฒนธรรมไทย และนำมาใช้อย่างถูกต้องและเหมาะสม', 'during', 'ต 2.2 ม.4-6/2', 'วิเคราะห์/อภิปรายความเหมือนและความแตกต่างระหว่างวิถีชีวิต ความเชื่อ และวัฒนธรรมของเจ้าของภาษากับของไทย และนำไปใช้อย่างมีเหตุผล', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-18', 'สาระที่ 3 ภาษากับความสัมพันธ์กับกลุ่มสาระการเรียนรู้อื่น', 'ม.4-6', 'ต 3.1', 'ใช้ภาษาต่างประเทศในการเชื่อมโยงความรู้กับกลุ่มสาระการเรียนรู้อื่น และเป็นพื้นฐานในการพัฒนา แสวงหาความรู้ และเปิดโลกทัศน์ของตน', 'during', 'ต 3.1 ม.4-6/1', 'ค้นคว้า/สืบค้น บันทึก สรุป และแสดงความคิดเห็นเกี่ยวกับข้อมูลที่เกี่ยวข้องกับกลุ่มสาระการเรียนรู้อื่นจากแหล่งการเรียนรู้ต่าง ๆ และนำเสนอด้วยการพูดและการเขียน', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-19', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.4-6', 'ต 4.1', 'ใช้ภาษาต่างประเทศในสถานการณ์ต่าง ๆ ทั้งในสถานศึกษา ชุมชน และสังคม', 'final', 'ต 4.1 ม.4-6/1', 'ใช้ภาษาสื่อสารในสถานการณ์จริง/สถานการณ์จำลองที่เกิดขึ้นในห้องเรียน สถานศึกษา ชุมชน และสังคม', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-20', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.4-6', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.4-6/1', 'ใช้ภาษาต่างประเทศในการสืบค้น/ค้นคว้า รวบรวม วิเคราะห์ และสรุปความรู้/ข้อมูลต่าง ๆ จากสื่อและแหล่งการเรียนรู้ต่าง ๆ ในการศึกษาต่อและประกอบอาชีพ', TRUE);
INSERT INTO "Indicators" ("indicatorId", "learningArea", "gradeLevel", "standardCode", "standardText", "indicatorType", "indicatorCode", "indicatorText", "isActive") VALUES ('IND-10-21', 'สาระที่ 4 ภาษากับความสัมพันธ์กับชุมชนและโลก', 'ม.4-6', 'ต 4.2', 'ใช้ภาษาต่างประเทศเป็นเครื่องมือพื้นฐานในการศึกษาต่อ การประกอบอาชีพ และการแลกเปลี่ยนเรียนรู้กับสังคมโลก', 'during', 'ต 4.2 ม.4-6/2', 'เผยแพร่/ประชาสัมพันธ์ข้อมูลข่าวสารของโรงเรียน ชุมชน และท้องถิ่น/ประเทศชาติเป็นภาษาต่างประเทศ', TRUE);
