INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('A012', 'assessmentTemplate', '[A] การเข้าร่วมกิจกรรมทางภาษาและวัฒนธรรม...', '{"group": "English_Communication", "domain": "A", "measure": "การเข้าร่วมกิจกรรมทางภาษาและวัฒนธรรม", "method": "สังเกตการเข้าร่วมกิจกรรมและการแสดงออก", "tool": "แบบสังเกตพฤติกรรม; แบบประเมินการมีส่วนร่วม", "criteria": "เข้าร่วมกิจกรรมครบและอยู่ในระดับดีขึ้นไป"}', '', '', TRUE);
INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('A013', 'assessmentTemplate', '[A] ความเชื่อมั่นในการใช้ภาษาอังกฤษและมารยาท...', '{"group": "English_Communication", "domain": "A", "measure": "ความเชื่อมั่นในการใช้ภาษาอังกฤษและมารยาทสังคมระหว่างบุคคล", "method": "สังเกตพฤติกรรมการสื่อสาร/สะท้อนคิดหลังทำกิจกรรม", "tool": "แบบสังเกต; แบบประเมินตนเอง; Reflection form", "criteria": "ระดับคุณภาพดีขึ้นไป"}', '', '', TRUE);
INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('A014', 'assessmentTemplate', '[K] ผู้เรียนอธิบายสาระสำคัญของเรื่อง/บทเรียน...', '{"group": "KPA_Generic", "domain": "K", "measure": "ผู้เรียนอธิบายสาระสำคัญของเรื่อง/บทเรียนได้", "method": "ตั้งคำถามสั้น ๆ; สังเกตการตอบคำถาม", "tool": "แบบทดสอบสั้น; บันทึกการสังเกต", "criteria": "ผ่านเกณฑ์การประเมินในระดับดีขึ้นไป"}', '', '', TRUE);
INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('A015', 'assessmentTemplate', '[P] ผู้เรียนปฏิบัติภาระงานตามขั้นตอนที่กำหนด...', '{"group": "KPA_Generic", "domain": "P", "measure": "ผู้เรียนปฏิบัติภาระงานตามขั้นตอนที่กำหนดได้อย่างถูกต้อง", "method": "ให้ผู้เรียนปฏิบัติชิ้นงาน/กิจกรรมตามขั้นตอน", "tool": "แบบบันทึกการปฏิบัติงาน; Rubric", "criteria": "ผ่านเกณฑ์การประเมินในระดับดีขึ้นไป"}', '', '', TRUE);
INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('A016', 'assessmentTemplate', '[A] ผู้เรียนตระหนักถึงคุณค่าและความสำคัญของเ...', '{"group": "KPA_Generic", "domain": "A", "measure": "ผู้เรียนตระหนักถึงคุณค่าและความสำคัญของเรื่องที่เรียน", "method": "สังเกตพฤติกรรมและสัมภาษณ์สั้น", "tool": "Rubric ประเมินทัศนคติ; แบบสะท้อนคิด", "criteria": "ผ่านเกณฑ์การประเมินในระดับดีขึ้นไป"}', '', '', TRUE);
