INSERT INTO "BasicOptions" ("optionId", "optionType", "optionName", "optionText", "gradeLevel", "subjectId", "isActive") VALUES ('OPT-ESS-001', 'essentialConceptTemplate', 'สาระสำคัญภาษาเพื่อการสื่อสาร', 'การเรียนรู้คำศัพท์ สำนวน และโครงสร้างภาษาอังกฤษช่วยให้ผู้เรียนสามารถใช้ภาษาเพื่อสื่อสารในสถานการณ์ใกล้ตัวได้อย่างเหมาะสม', '', '', TRUE);